        if (!gate || gate.enabled === false) continue;
        var name = gate.name || ('gate_' + (i + 1));
        var command = gate.command ? String(gate.command).replace(/\{ticketKey\}/g, options.ticketKey || '') : null;
        if (!command) continue;
