            collectInstructionFiles(rel, acc); // subdirectory (absolute probe)
        }
    });
    return acc;
}

// Build the union reference closure of all root configs.
// Returns { reachable: {path->true}, dangling: [path] }.
function buildClosure() {
    var reachable = {};
    var dangling = {};
    var queue = [];

    function scanFile(p) {
