})();

// repo-relative path -> absolute filesystem path
function fsPath(p) { return ROOT + '/' + p; }

function rebase(p) {
    if (p.indexOf('./') === 0) p = p.slice(2);
    if (p.indexOf('agents/') === 0) p = p.slice(7);
