```js
var MISSING_RESPONSE_STAGE = 'missing_response';
var MISSING_RESPONSE_DEFAULT_TIMEOUT_SECONDS = 2400; // 40 min hard cap

function buildMissingResponsePrompt(options) { ... }

function resumeOnceForMissingResponse(options) {
    options = options || {};
    var customParams = options.customParams || {};
    var config = normalizeConfig(customParams, 'missingResponse');
    if (!isFeedbackEnabled(customParams, 'missingResponse') || config.enabled === false) {
        return { attempted: false, reason: 'disabled' };
    }
    var errorText = String(options.error || '');
    if (isNonRecoverable(errorText, config)) {
        return { attempted: false, reason: 'non-recoverable' };
    }
    ensureFeedbackDir();
    var key = sanitizeId((options.ticketKey || 'unknown') + '_' + MISSING_RESPONSE_STAGE);
    var markerPath = 'outputs/feedback/' + key + '.attempt';
    var attempt = getAttempt(markerPath);
    if (attempt >= 1) {
        return { attempted: false, reason: 'attempts-exhausted', attempts: attempt };
    }
    setAttempt(markerPath, '1');
    var promptPath = 'outputs/feedback/' + key + '.md';
    writeFile(promptPath, buildMissingResponsePrompt({ ticketKey: options.ticketKey }));
    var timeoutSeconds = parseInt(config.timeoutSeconds, 10);
    if (!timeoutSeconds || timeoutSeconds < 1) timeoutSeconds = MISSING_RESPONSE_DEFAULT_TIMEOUT_SECONDS;
    var command = 'bash -c "timeout ' + timeoutSeconds + ' bash agents/scripts/run-agent.sh --continue ' + promptPath + '"';
    console.log('Feedback loop: one bounded resume for missing outputs/response.md (cap ' + timeoutSeconds + 's)');
    var timedOut = false;
    try {
        runCommand(command);
    } catch (e) {
        // A `timeout` kill surfaces as a command failure (exit 124) — the
        // attempt stays bounded; caller falls back to the cold reset.
        timedOut = true;
        console.warn('Bounded resume command failed (treated as resume failure): ' + e);
    }
    return { attempted: true, timedOut: timedOut, promptPath: promptPath };
}
