);

    var mod = loadModule(
        'js/developBugAndCreatePR.js',
        makeRequire({
            './config.js': configModule,
            './common/gitStaging.js': gitStagingModule,
            './configLoader.js': configLoaderModule,
            './common/outputFiles.js': outputFiles,
            './developTicketAndCreatePR.js': {
