                loaded.commands.push(args.command);
                if (args.command === 'flutter analyze') {
                    gateCalls++;
                    if (gateCalls < 3) throw new Error('analyze failed');
                }
                return '';
            }
        });

        var result = loaded.mod.runQualityGates({
            ticketKey: 'TS-3',
            customParams: {
                feedbackLoop: {
                    qualityGates: {
