}

// Recursively collect repo-relative 'instructions/**.md' paths.
function collectInstructionFiles(dir, acc) {
    acc = acc || {};
    var out = file_list(fsPath(dir));
    if (typeof out === 'string') out = JSON.parse(out);
    ((out && out.entries) || []).forEach(function (e) {
