}

function takeValue(opts, key, a, argv, i) {
  const prefix = `--${key}=`;
  if (a.startsWith(prefix)) {
    opts[key] = a.slice(prefix.length);
    return i;
  }
  const v = argv[i + 1];
  if (v == null) throw new Error(`--${key} requires a value`);
  opts[key] = v;
  return i + 1;
}
