};

function parseArgs(argv) {
  const opts = newOpts();
  for (let i = 0; i < argv.length; i++) {
    i = applyArg(opts, argv, i);
  }
  validateOpts(opts);
  opts.thresholdValue = parseThreshold(opts.threshold);
