The bounded resume wrapper:

```js
// ── gh-775: one bounded resume for a missing deliverable ──────────
// A dev agent can finish all real work and still lose the leg to a HUNG
// background verification job: the post-action finds outputs/response.md
// missing and cold-resets a session that was one "write the deliverable"
// step away from done (live fa gh-1341, run 37521704313). Before that cold
// reset, the dev post-action makes exactly ONE bounded resume attempt so the
// still-alive session can finish and write the deliverable.
var MISSING_RESPONSE_STAGE = 'missing_response';

function resumeOnceForMissingResponse(options) {
    options = options || {};
    var customParams = options.customParams || {};
    var root = customParams.feedbackLoop || {};
    var scoped = (root.missingResponse && typeof root.missingResponse === 'object')
        ? root.missingResponse : {};
    if (scoped.enabled === false) {
        return { attempted: false, reason: 'disabled' };
    }
    // Same master switch as every other resume path: the feedback loop must
    // be enabled (root or this section) or the wrapper is never re-invoked.
    if (!isFeedbackEnabled(customParams, 'missingResponse')) {
        return { attempted: false, reason: 'disabled' };
    }

    var maxAttempts = 1; // exactly one attempt, by design (gh-775 non-goal: no multi-resume)
    var timeoutSeconds = parseInt(scoped.timeoutSeconds, 10);
    if (!timeoutSeconds || timeoutSeconds < 1) {
        timeoutSeconds = DEFAULT_MISSING_RESPONSE_TIMEOUT_SECONDS;
    }

    try {
        var result = resumeAgent({
            ticketKey: options.ticketKey,
            customParams: {
                feedbackLoop: {
                    enabled: true,
                    missingResponse: { enabled: true, maxAttempts: maxAttempts }
                }
            },
            section: 'missingResponse',
            stage: MISSING_RESPONSE_STAGE,
            error: options.error || '',
            promptOverride: options.promptOverride || buildMissingResponsePrompt({
                ticketKey: options.ticketKey
            }),
            timeoutSeconds: timeoutSeconds
        });
        return result;
    } catch (e) {
        // A failed/timed-out wrapper invocation is a resume FAILURE, not a
        // crash — swallowing it lets the caller re-check the deliverable and
        // fall back to the EXISTING cold reset, byte-identical (gh-775 AC4).
        console.warn('Bounded resume for missing outputs/response.md failed/timed out:', e);
        return { attempted: true, failed: true, error: e && e.message ? e.message : String(e) };
