        var result = loaded.mod.resumeOnceForMissingResponse({
            ticketKey: 'TS-1',
            customParams: { feedbackLoop: { enabled: true, missingResponse: { enabled: false } } }
        });

        assert.equal(result.attempted, false);
        assert.deepEqual(loaded.commands, []);
    });

